<script setup lang="ts">
import { computed } from 'vue';
import { formatTime, statusLabels, type Snapshot } from '../types/simulation';
import type { SceneEventVisual } from '../scene/eventFocus';
import { demoCameraCue, demoChangeRows, demoLandingSite, demoIntro, demoOutcome, type ComparisonMode, type FlightChange } from '../scene/demoStory';
const props = defineProps<{ state: Snapshot; event: SceneEventVisual | null; changes: FlightChange[]; mode: ComparisonMode; busy: boolean; focusId?: string; cameraPhase?: string }>();
const emit = defineEmits<{ mode: [value: ComparisonMode]; play: []; advance: [steps: number]; focus: []; close: []; inspect: [id:string] }>();
const finished = computed(() => props.state.simulation.demo_complete && (props.state.simulation.demo_scenario !== 'full' || props.state.metrics.active_mission_count === 0));
const intro = computed(() => demoIntro(props.state));
const cue = computed(() => demoCameraCue(props.state));
const target = computed(() => props.state.aircraft.find(a=>a.id===(props.focusId || props.event?.primaryAircraftId || cue.value?.aircraftId)));
const example = computed(() => props.changes.find(c=>c.aircraftId===target.value?.id) ?? props.changes[0]);
const outcome = computed(() => props.event ? demoOutcome(props.state, props.event, props.changes) : null);
const landingSite = computed(() => demoLandingSite(props.state,props.event));
const decisionActor = computed(() => {const value=props.event?.kind==='conflict' ? props.state.events.find(e=>e.id===props.event?.id)?.result.aircraft_id : '';return typeof value==='string' ? value : '';});
const rows = computed(() => props.event ? demoChangeRows(props.state,props.event,props.changes,example.value?.aircraftId) : []);
const countdownProgress = computed(() => Math.min(100,Math.max(0,props.state.simulation.time_s/intro.value.at*100)));
const delta = computed(() => {const item=example.value;if(!item)return '';const value=item.after.distance-item.before.distance;return `${value>=0?'+':'−'}${Math.abs(value).toFixed(0)} m`;});
const modes: { id: ComparisonMode; label: string }[] = [{ id: 'both', label: '路线对比' }, { id: 'before', label: '原计划' }, { id: 'after', label: '新计划' }];
</script>
<template>
  <article class="demo-story" :class="{ 'has-event': event }" aria-label="演示变化讲解">
    <div class="story-kicker"><span><i />DEMO / {{ event ? '变化对比' : '开场观察' }}</span><button title="收起演示讲解" aria-label="收起演示讲解" @click="emit('close')">×</button></div>
    <h3>{{ event?.label ?? intro.title }}<small v-if="event">{{ formatTime(event.simulationTime) }}</small></h3>
    <div v-if="target" class="observation-target"><div><span>观察对象</span><b>{{ target.id }}</b></div><p>{{ ['wide','establish','approach'].includes(cameraPhase || '') ? '镜头推进中' : statusLabels[target.status] || target.status }}<small>{{ target.position.z.toFixed(0) }} m · {{ target.speed.toFixed(1) }} m/s</small></p></div>
    <template v-if="!event">
      <p class="intro">{{ intro.intent }}</p>
      <div class="intro-stages"><span class="active">① 锁定目标</span><i>→</i><span>② 事件触发</span><i>→</i><span>③ 方案改变</span></div>
      <div v-if="cue" class="initial-plan"><span><i />当前原计划</span><b>{{ (cue.plan.distance/1000).toFixed(2) }} km</b><small>起始任务航程</small></div>
      <div class="direction-grid"><div v-for="(label,i) in ['东 →','西 ←','北 ↑','南 ↓']" :key="label"><span>{{ label }}</span><b>{{ intro.headings[i] }}<small>架</small></b></div></div>
      <div class="countdown"><span>事件倒计时 <small>仿真时间</small></span><b>{{ intro.countdown>0 ? `${intro.countdown.toFixed(0)} s` : '下一步触发' }}</b></div>
      <div class="countdown-track" role="progressbar" aria-label="事件前运行进度" :aria-valuenow="countdownProgress" aria-valuemin="0" aria-valuemax="100"><i :style="{width:`${countdownProgress}%`}" /></div>
      <p class="sample-note">选择场景即推进镜头，启动后观察目标如何改变计划。</p>
    </template>
    <template v-else-if="outcome">
      <div class="decision-summary"><span>系统作出的改变 <b v-if="decisionActor">· {{ decisionActor }}</b></span><p>{{ outcome.decision }}</p></div>
      <div v-if="rows.length" class="change-board" role="table" aria-label="事件前后变化对比"><div class="change-header" role="row"><span>变化项</span><b>事件前</b><i /><b>处置后</b></div><div v-for="row in rows" :key="row.label" class="change-row" role="row"><span role="rowheader">{{ row.label }}</span><b role="cell">{{ row.before }}</b><i>→</i><b role="cell">{{ row.after }}</b></div></div>
      <p v-if="landingSite" class="site-note">独立场坪 {{ landingSite.size }}×{{ landingSite.size }} m · 道路退距 ≥{{ landingSite.setback }} m</p>
      <div class="live-feedback" :class="{attention:event.phase==='attention'}" aria-live="polite"><span><i />执行反馈 · 当前实况</span><p>{{ outcome.current }}</p></div>
      <template v-if="changes.length">
        <div class="comparison-controls" role="group" aria-label="飞行计划对比"><button v-for="option in modes" :key="option.id" :class="{active:mode===option.id}" :aria-pressed="mode===option.id" @click="emit('mode',option.id)">{{ option.label }}</button></div>
        <div class="path-legend"><span><i class="before" />原计划</span><b>→</b><span><i class="after" />新计划</span><small>航程 {{ delta }}</small></div>
        <div v-if="changes.length>1" class="representatives" role="group" aria-label="选择对比飞机"><button v-for="item in changes" :key="item.aircraftId" :class="{active:example?.aircraftId===item.aircraftId}" :aria-pressed="example?.aircraftId===item.aircraftId" @click="emit('inspect',item.aircraftId)">{{ item.aircraftId }}</button></div>
        <p class="sample-note"><template v-if="decisionActor && target?.id!==decisionActor">当前观察机保持原计划，由 {{ decisionActor }} 让行。</template><template v-else-if="changes.every(c=>JSON.stringify(c.before.path)===JSON.stringify(c.after.path))">线路重合，变化体现在等待或速度。</template><template v-else>已突出当前观察飞机的路线。</template>{{ changes.some(c=>c.before.pathOmitted||c.after.pathOmitted) ? '部分路线未记录。' : '' }}飞机为当前实况。</p>
      </template>
      <p v-else class="sample-note">此记录未保存前后路线，显示真实处置结果。</p>
    </template>
    <div class="story-actions"><button class="play" :disabled="busy || finished" @click="emit('play')">{{ finished ? '演示已完成' : state.simulation.running ? 'Ⅱ 暂停讲解' : '▶ 讲解播放 · 5×' }}</button><button v-if="!event && !state.simulation.running" :disabled="busy" @click="emit('advance',intro.steps)">推进到事件 ↗</button><button v-else @click="emit('focus')">{{ event ? '重播运镜 ↗' : '重播开场 ↗' }}</button></div>
  </article>
</template>
